create or replace function public.address_key(a text) returns text language sql immutable set search_path to '' as $fn$ select case when m is null then null else m[1] || ' ' || left((select t from unnest(regexp_split_to_array(trim(regexp_replace(m[2], '[^a-z0-9 ]', ' ', 'g')), '\s+')) with ordinality u(t, i) where t <> '' and not (t in ('n','s','e','w','north','south','east','west') and i < array_length(regexp_split_to_array(trim(regexp_replace(m[2], '[^a-z0-9 ]', ' ', 'g')), '\s+'), 1)) order by i limit 1), 4) end from (select regexp_match(lower(coalesce(a, '')), '^\s*(\d+)\S*\s+(.*)$') m) x $fn$;
comment on function public.address_key(text) is 'House number + first 4 letters of the street name, skipping a leading direction. "946 Flanders Ave. 44314" and "946 Flanders Avenue, Akron OH" both give "946 flan".';

create or replace function public.match_completion_log_rows() returns jsonb language plpgsql security definer set search_path to 'public' as $fn$ declare r record; c int; v_job uuid; v_method text; v_note text; n_m int := 0; n_a int := 0; n_u int := 0; begin if auth.uid() is not null and not public.is_admin() then raise exception 'office only' using errcode = '42501'; end if; for r in select * from public.completion_log_rows where match_status in ('unmatched', 'ambiguous') loop v_job := null; v_method := null; v_note := null; if r.ghl_project_id is not null then select id into v_job from public.jobs where ghl_project_display_id = r.ghl_project_id order by created_at limit 1; if v_job is not null then v_method := 'ghl_project_id'; end if; end if; if v_job is null then select count(*) into c from public.jobs j where public.address_key(j.customer_address) = public.address_key(r.address); if c = 1 then select id into v_job from public.jobs j where public.address_key(j.customer_address) = public.address_key(r.address); v_method := 'address'; elsif c > 1 then select id into v_job from public.jobs j where public.address_key(j.customer_address) = public.address_key(r.address) and abs(coalesce(j.contract_amount, 0) - coalesce(r.contract_amount, -1)) < 1 and (select count(*) from public.jobs j2 where public.address_key(j2.customer_address) = public.address_key(r.address) and abs(coalesce(j2.contract_amount, 0) - coalesce(r.contract_amount, -1)) < 1) = 1; if v_job is not null then v_method := 'address+amount'; else v_note := c || ' jobs at this address and no single contract-amount match'; end if; end if; end if; if v_job is null and v_note is null then select count(*) into c from public.jobs j where lower(j.customer_name) like '%' || lower(split_part(regexp_replace(r.customer, '\s*\(.*\)|#\d+', '', 'g'), ' ', array_length(regexp_split_to_array(trim(regexp_replace(r.customer, '\s*\(.*\)|#\d+', '', 'g')), '\s+'), 1))) || '%' and abs(coalesce(j.contract_amount, 0) - coalesce(r.contract_amount, -1)) < 1; if c = 1 then select id into v_job from public.jobs j where lower(j.customer_name) like '%' || lower(split_part(regexp_replace(r.customer, '\s*\(.*\)|#\d+', '', 'g'), ' ', array_length(regexp_split_to_array(trim(regexp_replace(r.customer, '\s*\(.*\)|#\d+', '', 'g')), '\s+'), 1))) || '%' and abs(coalesce(j.contract_amount, 0) - coalesce(r.contract_amount, -1)) < 1; v_method := 'name+amount'; end if; end if; if v_job is not null then update public.completion_log_rows set job_id = v_job, match_method = v_method, match_status = 'matched', match_note = null where id = r.id; n_m := n_m + 1; elsif v_note is not null then update public.completion_log_rows set match_status = 'ambiguous', match_note = v_note where id = r.id; n_a := n_a + 1; else update public.completion_log_rows set match_status = 'unmatched', match_note = 'no job at this address or with this name and amount' where id = r.id; n_u := n_u + 1; end if; end loop; return jsonb_build_object('matched', n_m, 'ambiguous', n_a, 'unmatched', n_u); end $fn$;
comment on function public.match_completion_log_rows() is 'Links completion_log_rows to jobs: GHL project id if the row has one, else address key (unique, or unique among same-address jobs by contract amount), else customer last name + contract amount. Only touches unmatched/ambiguous rows, so manual matches stick.';
revoke execute on function public.match_completion_log_rows() from public, anon;
grant execute on function public.match_completion_log_rows() to authenticated;;
